body {
    margin:0;
    color:#333;
}

a {
    text-decoration:none;
    color:#006699;
}

p {
    margin:0px;
}

img {
    border:0;
    margin:0;
}

/* container */
#container {
    width:540px;
    margin:0 auto;
}

#content {
    width:500px;
    margin:0 20px;
}

/* header */
#header {
    border-bottom:1px solid #eaeaea;
    padding-top:10px;
    padding-left:0px;
    padding-right:0px;
    padding-bottom:10px;
}

#title p{
    font-size:20px;
    font-family: "arial", "sans-serif";
}

#amazonLogo{
    width:107px;
    height:31px;
}

/* verification msg */
#verificationMsg {
    padding-left:0;
    padding-top:9px;
    padding-bottom:9px;
}

#verificationMsg p {
    font-size:14px;
    font-family: "arial", "sans-serif";
}

#verificationMsg .otp {
    font-size:18px;
    font-weight:bold;
    padding-top:18px;
}

/* account security */
#accountSecurity {
    padding-left:0;
    padding-top:9px;
    padding-bottom:9px;
}

#accountSecurity p {
    font-size:14px;
    font-family: "arial", "sans-serif";
}

/* closing */
#closing {
    padding-left:0;
    padding-top:9px;
    padding-bottom:9px;
}

#closing p {
    font-size:14px;
    font-family: "arial", "sans-serif";
}


















